import {icon} from './icons.js';
import {parametersPanel,posePanel,scopeFor,getAt,setAt} from './parameters.js';
import {ReferenceGuides} from './guides.js';
import {setupArt} from './art-ui.js';
import {motionPanel,defaultMotion} from './part-motion.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v)),copy=v=>structuredClone(v);
const state={project:null,id:null,mode:'make',selected:'eye0',tool:'select',tab:'motion',playing:true,time:0,duration:10,dirty:false,needsBuild:false,history:[],future:[],drawing:null,expression:'neutral',mouth:null,face:null,mic:null,recording:false};
let miniAvatar=null,lastMiniFrame=0;let avatar=null,lastFrame=performance.now(),audioCtx=null,audioSource=null,analyser=null,envelope=null,audioBuffer=null,toastTimer,loadToken=0,savePromise=null;
let micStream=null,camStream=null,camWorker=null,camBusy=false,lastCam=0,faceLastSeen=0,neutralFace=null,rawFace=null,smoothFace={};
const guides=new ReferenceGuides($('#reference-guides'),$('#static-reference'));
state.editorView={zoom:1,panX:0,panY:0};
const voice=$('#voice'),stage=$('#stage'),overlay=$('#overlay'),timeline=$('#timeline'),channel=new BroadcastChannel('youxing-live');
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{if(!el.querySelector('svg'))el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon));});}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function showError(e){console.error(e);toast(e.message||String(e));}
async function api(url,data,raw=false){const r=await fetch(url,data===undefined?{}:{method:'POST',headers:raw?{}:{'Content-Type':'application/json'},body:raw?data:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.error||'操作失败');return v;}
function settings(){return state.project?.settings||{};}
function updateSave(){const el=$('#save-state');el.textContent=state.needsBuild?'轮廓已修改 · 待更新':state.dirty?'尚未保存':'已保存到本机';$('#save').disabled=!!savePromise;}
function checkpoint(){if(!state.project)return;state.history.push(copy({rig:state.project.rig,regions:state.project.regions,settings:state.project.settings,keyframes:state.project.keyframes,name:state.project.name,layerVisibility:state.project.layerVisibility,motions:state.project.motions}));if(state.history.length>40)state.history.shift();state.future=[];}
function changed(build=false){state.dirty=true;state.needsBuild ||= build;updateSave();}
function setBusy(on,text='正在加载形象…'){$('#stage-loading').hidden=!on;$('#stage-loading span:last-child').textContent=text;}
async function listProjects(){const all=await api('/api/projects');$('#project-select').innerHTML=all.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');if(state.id)$('#project-select').value=state.id;return all;}
async function openProject(id,{home=false}={}){
 const token=++loadToken;state.playing=false;voice.pause();stopMic();stopCamera();setBusy(true);$('#home').hidden=!home;
 try{const p=await api('/api/projects/'+id);if(token!==loadToken)return;state.id=id;state.project=p;state.project.keyframes=(state.project.keyframes||[]).map(k=>k.channel==='angleZ'?{...k,channel:'bodyAngleZ'}:k);state.project.motions||={};state.partValue={};state.sweep=null;state.tab='motion';state.originalRig=copy(p.rig);state.pose={};state.editorView={zoom:1,panX:0,panY:0};await guides.load('/projects/'+id+'/source.png');state.selected='head';state.time=0;state.duration=10;state.dirty=false;state.needsBuild=false;state.history=[];state.future=[];state.mouth=null;state.expression='neutral';envelope=null;audioBuffer=null;voice.removeAttribute('src');voice.load();$('#character-title').textContent=p.name;$('#project-select').value=id;$('#origin-pill').textContent=p.kind==='sample'?'大肥鱼1号案例':'单图制作';$('#background').value=p.settings.background||'checker';setBackground(p.settings.background||'checker');await reloadAvatar();guides.mode='original';guides.on=true;$('#reference-mode').value='original';$('#toggle-guides').classList.add('active');if(p.hasAudio){await loadAudio('/projects/'+id+'/voice.wav','工程配音');}else state.playing=true;renderLayers();renderInspector();updateSave();updatePlayButton();await listProjects();}catch(e){showError(e);}finally{if(token===loadToken)setBusy(false);}
}
async function reloadAvatar(){
 if(!state.project?.meta)return;avatar?.destroy();miniAvatar?.destroy();miniAvatar=null;avatar=null;const canvas=$('#avatar');
 avatar=await MeshAvatar.createMeshAvatar(canvas,{rig:state.project.rig,assetsBase:'/projects/'+state.id+'/built/',manual:true,padTop:state.project.rig.view.padTop,padSide:state.project.rig.view.padSide,preserveMouthForm:true,revision:state.project.meta.build});
 avatar.setAutoIdle(false);avatar.setAutoMotion(false);avatar.setEditorView(state.editorView);avatar.setSwayGain(settings().sway??.8);avatar.setTalkGain(settings().talkGain??1);avatar.setEditorMesh(state.tool==='grid');
 for(const [name,visible] of Object.entries(state.project.layerVisibility||{}))avatar.setLayerVisible(name,visible);
 avatar.setParameters(neutral());avatar.advance(0);miniAvatar=await MeshAvatar.createMeshAvatar($('#mini-avatar'),{rig:state.project.rig,assetsBase:'/projects/'+state.id+'/built/',manual:true,padTop:.03,padSide:.04,revision:state.project.meta.build,preserveMouthForm:true});miniAvatar.setAutoIdle(false);miniAvatar.setAutoMotion(false);for(const [name,visible] of Object.entries(state.project.layerVisibility||{}))miniAvatar.setLayerVisible(name,visible);miniAvatar.setParameters(neutral());miniAvatar.advance(0);lastMiniFrame=performance.now();renderOverlay();
}
function neutral(){return {...Object.fromEntries(MeshAvatar.PARAMS.map(p=>[p.id,p.def])),angleX:0,angleY:0,angleZ:0,bodyAngleZ:0,breath:.3,eyeLOpen:1,eyeROpen:1,mouthOpen:0,mouthForm:0,gazeX:0,gazeY:0,eyeSmile:0};}
function partList(){if(!state.project)return[];const p=state.project;let items=[{id:'head',name:'头部',kind:'region',group:'头部与发丝',icon:'layers'},{id:'body',name:'身体',kind:'region',group:'头部与发丝',icon:'move'}];for(const reg of p.regions||[])items.push({id:reg.id,name:reg.name,kind:'pixel',group:'头部与发丝',asset:'detail_'+reg.id,reg});
 for(let i=0;i<2;i++){const name=i===0?'画面左眼':'画面右眼';items.push({id:'eye'+i,name,kind:'region',group:'五官与差分',icon:'eye'});for(const [n,t] of [['ball','眼球'],['lash','上睫毛'],['low','下眼睑'],['crease','眼褶']])items.push({id:`eye${i}_${n}`,name:t,kind:'pixel',group:'五官与差分',asset:`eye${i}_${n}`,sub:true});}
 items.push({id:'mouth',name:'嘴型与口型差分',kind:'region',group:'五官与差分',icon:'smile'});
 for(const [n,rect] of Object.entries(p.sprites?.layers||{}))if(n.startsWith('mouth_'))items.push({id:'sprite_'+n,name:({mouth_a:'张口 A',mouth_a_half:'半张口',mouth_i:'横口 I',mouth_o:'圆口 O'})[n]||n,kind:'sprite',asset:'sprites/'+n,sub:true,group:'五官与差分'});
 for(const a of p.rig.appendages||[])items.push({id:a.name,name:a.kind==='tail'?'独立尾巴':a.name==='ear-left'?'左侧耳饰':'右侧耳饰',kind:a.layer?'pixel':'region',asset:a.layer,group:'身体与附属',appendage:a});
 for(const [scope,name,ico] of [['face','面部细节','smile'],['cheeks','腮红位置','smile'],['strands','发丝骨架','polygon'],['appendages','尾巴与耳饰参数','tail'],['mesh','网格精度','grid'],['view','画布与视线','expand']])if(p.rig[scope]!==undefined)items.push({id:'rig-'+scope,name,rigScope:scope,kind:'region',group:'完整绑定参数',icon:ico});return items;}
function currentPart(){return partList().find(p=>p.id===state.selected)||partList()[0];}
function thumbUrl(p){if(['head','body','mouth','eye0','eye1'].includes(p.id))return `/projects/${state.id}/previews/${p.id}.png?v=${state.project.meta?.build||1}`;return p.asset?`/projects/${state.id}/built/${p.asset}.png?v=${state.project.meta?.build||1}`:`/projects/${state.id}/source.png`;}
function renderLayers(){const list=partList(),q=$('#layer-search').value.trim();let group='';$('#layer-tree').innerHTML=list.filter(p=>(q||!p.sub)&&(q||!p.rigScope||p.rigScope==='strands')&&(!q||p.name.includes(q))).sort((a,b)=>{const order=['head','body','eye0','eye1','mouth','aquatic-tail'];return (order.includes(a.id)?order.indexOf(a.id):50)-(order.includes(b.id)?order.indexOf(b.id):50);}).map(p=>{const g=p.group!==group?`<div class="layer-group"><span>${esc(p.group)}</span></div>`:'';group=p.group;const hidden=state.project.layerVisibility?.[p.asset]===false;return g+`<div class="layer-row ${p.sub?'sub':''} ${state.selected===p.id?'active':''} ${hidden?'hidden-layer':''}" data-part="${p.id}" role="button" tabindex="0" aria-label="选择${esc(p.name)}"><button class="visibility" data-visible="${p.id}" aria-label="${hidden?'显示':'隐藏'}${esc(p.name)}" title="${p.kind==='region'?'形变区域不等同像素层':'显示/隐藏图层'}">${icon(hidden?'hidden':p.icon||'eye',14)}</button><img class="thumb" src="${thumbUrl(p)}" alt="" loading="lazy"><span class="layer-name">${esc(p.name)}</span><span class="kind">${p.kind==='region'?'形变区':p.kind==='sprite'?'差分':'图层'}</span></div>`;}).join('')||'<p class="note" style="padding:15px">没有匹配的部件</p>';$('#layer-count').textContent=`${list.filter(x=>x.kind==='pixel').length} 个独立像素层 · ${list.filter(x=>x.kind==='sprite').length} 个嘴型差分`;}
function range(label,key,value,min=0,max=1,step=.01){return `<div class="field"><label for="set-${key}">${label}</label><input id="set-${key}" data-setting="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"><output>${Number(value).toFixed(2)}</output></div>`;}
function check(label,key,value){return `<label class="field"><span>${label}</span><input type="checkbox" data-setting="${key}" ${value?'checked':''}></label>`;}
function expressions(){return `<div class="expression-grid">${[['neutral','自然'],['smile','微笑'],['surprise','惊讶'],['wink','眨单眼'],['halfLidded','半闭眼'],['closed','闭眼']].map(([v,n])=>`<button data-expression="${v}" class="${state.expression===v?'active':''}">${icon(v==='neutral'?'select':v==='smile'?'smile':'eye',17)}${n}</button>`).join('')}</div>`;}
function renderInspector(){if(!state.project)return;const p=currentPart(),s=settings();let html='';
 if(state.mode==='make'){
  html=`<div class="panel-heading"><h2>${esc(p?.name||'形象')}</h2><span class="pill">${p?.kind==='region'?'形变区域':'独立素材'}</span></div><div class="inspector-tabs">${[['motion','动作'],['contour','绑定'],['parameters','高级']].map(([k,n])=>`<button data-tab="${k}" class="${state.tab===k?'active':''}">${n}</button>`).join('')}</div>`;
  if(state.tab==='motion'){html+=motionPanel(p,state.project,state);}
  else if(state.tab==='parameters'){state.rigScope ||= scopeFor(p);html+=parametersPanel(state.project.rig,state.rigScope)+posePanel(state.pose);}
  else if(state.tab==='layer'){html+=`<section class="inspector-section"><img class="zoom-crop" src="${thumbUrl(p)}" alt="${esc(p.name)}局部素材"><div class="field"><label>名称</label><input id="part-rename" value="${esc(p.name)}" ${p.reg?'':'readonly'} style="width:150px"></div><div class="field"><span>类型</span><span class="pill">${p.kind==='region'?'网格形变区域':p.kind==='sprite'?'口型差分素材':'透明 PNG 图层'}</span></div><p>${p.kind==='region'?'区域决定哪些像素跟随动作，不会自动生成独立素材。':p.kind==='sprite'?'口型由配音音量自动切换，也可在下方手动预览。':'独立像素素材已生成，可显示、隐藏及重新划定轮廓。'}</p>${p.reg?`<button class="secondary full" id="edit-region" style="margin-top:12px">编辑部件轮廓</button><button class="text-btn" id="delete-region" style="margin-top:12px">移除此细分图层</button>`:''}</section>`;
  }else if(state.tab==='contour'){const pts=getPoints();html+=`<section class="inspector-section"><h3>直接在画布上调整</h3><p>${pts?'拖动蓝色控制点调整轮廓。调整后点「更新分层与绑定」生效。':'这个部件使用整体绑定。选择双眼、头部、身体或自定义部件可编辑。'}</p><button class="secondary full" id="edit-region" style="margin-top:15px">显示控制点</button><div class="field"><span>控制点数量</span><span class="pill">${pts?.length||0}</span></div><button class="secondary full" id="inspector-rebuild">更新并预览</button></section>`;}
  if(state.tab==='layer')html+=`<section class="inspector-section"><h3>动作预览</h3>${range('摆动幅度','sway',s.sway??.8,0,2)}${range('说话动作','talkGain',s.talkGain??1,0,2)}${check('自然呼吸与轻摆','idle',s.idle!==false)}${check('自动眨眼','blink',s.blink!==false)}<button class="secondary full" id="test-blink" style="margin-top:10px">${icon('eye')}试眨一次</button></section>`;
  if(state.tab==='layer'&&state.selected.startsWith('eye')){const eye=state.selected.includes('1')?1:0;html+=`<section class="inspector-section"><h3>眼睛差分</h3><div class="sprite-grid">${[['open','睁眼'],['half','半闭'],['closed','闭眼']].map(([k,n])=>`<button data-eye-state="${k}"><img src="/projects/${state.id}/built/${k==='open'?`eye${eye}_ball.png`:`sprites/eyes_${k}_${eye}.png`}" alt="${n}" onerror="this.hidden=true"><span>${n}</span></button>`).join('')}</div><p class="inspector-note">新照片以网格变形闭眼；案例带独立绘制差分。</p></section>`;}
  if(state.tab==='layer')html+=`<section class="inspector-section"><h3>表情</h3>${expressions()}</section>`;
 }else if(state.mode==='voice'){
  html=`<div class="panel-heading"><h2>让形象跟着声音说话</h2></div><section class="inspector-section"><p>导入配音，自动分析真实音量并驱动口型。声音与动作在同一时间轴预览。</p><button class="primary full" id="voice-import" style="margin-top:16px">${icon('mic')}导入配音</button><button class="secondary full" id="voice-demo" style="margin-top:9px">试用大肥鱼1号口播</button><div class="field"><span>当前配音</span><span id="audio-name">${voice.hasAttribute('src')?'已加载本地配音':'尚未导入'}</span></div>${range('口型灵敏度','mouthGain',s.mouthGain??1.5,.3,4)}${range('说话动作','talkGain',s.talkGain??1,0,2)}</section><section class="inspector-section"><h3>口型检查</h3><div class="expression-grid">${[['auto','自动'],['closed','闭口'],['a','张口 A'],['a_half','半张口'],['i','横口 I'],['o','圆口 O']].map(([k,n])=>`<button data-mouth="${k}" class="${state.mouth===k?'active':''}">${n}</button>`).join('')}</div><p class="inspector-note">没有声音时嘴巴自然闭合；低音量可提高灵敏度。</p></section><section class="inspector-section"><h3>表情与动作</h3>${expressions()}${check('自然呼吸与轻摆','idle',s.idle!==false)}</section><section class="inspector-section"><h3>导出动画</h3><p>播放配音并录制 WebM；透明背景可保留 Alpha。也可在导出面板下载 PNG 和角色包。</p><button class="secondary full" id="voice-record" style="margin-top:12px">${icon('record')}录制当前动画</button></section>`;
 }else{
  const obs=location.origin+'/player.html?project='+state.id+'&bg='+(s.background==='checker'?'transparent':s.background||'transparent');
  html=`<div class="panel-heading"><h2>实时驱动</h2><span class="pill">本机连接</span></div><section class="inspector-section"><h3>麦克风口型</h3><p>只用声音即可说话，无需开启摄像头。</p><div id="mic-status" class="device-status ${micStream?'running':''}"><i class="dot"></i>${micStream?'麦克风已连接':'麦克风未开启'}</div><div class="meter"><b id="mic-meter"></b></div><button class="${micStream?'secondary':'primary'} full" id="toggle-mic">${icon('mic')}${micStream?'关闭麦克风':'开启麦克风'}</button>${range('口型灵敏度','mouthGain',s.mouthGain??1.5,.3,4)}</section><section class="inspector-section"><h3>摄像头表情与转头</h3><div id="camera-status" class="device-status ${camStream?'running':''}"><i class="dot"></i>${camStream?'等待面部信号':'摄像头未开启'}</div><div class="live-actions"><button class="secondary" id="toggle-camera">${icon('camera')}${camStream?'关闭':'开启摄像头'}</button><button class="secondary" id="calibrate">校准正面</button></div><p class="inspector-note">摄像头与音频均留在本机。先面朝正前方，再校准。</p></section><section class="inspector-section"><h3>输出到 OBS</h3><div class="url-box">${esc(obs)}</div><div class="live-actions"><button class="secondary" id="copy-obs">${icon('copy')}复制地址</button><button class="secondary" id="open-player">打开画面</button></div><p class="inspector-note">在 OBS 添加浏览器来源，建议 1080 × 1080。保持此工作台开启。工作台未连接时显示待机动作。</p></section><section class="inspector-section"><h3>快捷表情</h3>${expressions()}</section>`;
 }
 $('#inspector').innerHTML=html;icons($('#inspector'));
}
function getPoints(){const p=currentPart(),r=state.project?.rig;if(!p||!r)return null;if(p.reg)return p.reg.points;if(p.id==='eye0'||p.id.startsWith('eye0_'))return r.eyes[0].opening;if(p.id==='eye1'||p.id.startsWith('eye1_'))return r.eyes[1].opening;if(p.appendage)return p.appendage.outline;if(p.id==='head'||p.id==='body'){const e=p.id==='head'?r.head:r.body.chest;return [[e.cx-e.rx,e.cy-e.ry],[e.cx+e.rx,e.cy-e.ry],[e.cx+e.rx,e.cy+e.ry],[e.cx-e.rx,e.cy+e.ry]];}if(p.id==='mouth'){const e=r.mouth.area;return [[e.cx-e.rx,e.cy-e.ry],[e.cx+e.rx,e.cy-e.ry],[e.cx+e.rx,e.cy+e.ry],[e.cx-e.rx,e.cy+e.ry]];}return null;}
function screenPoint(pt){if(!avatar)return pt;const v=avatar.getViewport(),k=$('#avatar').clientWidth/v.width;return [(pt[0]*v.scale+v.offset[0])*k,(pt[1]*v.scale+v.offset[1])*k];}
function imagePoint(x,y){const r=overlay.getBoundingClientRect(),v=avatar.getViewport(),k=$('#avatar').clientWidth/v.width;return [clamp(((x-r.left)/k-v.offset[0])/v.scale,0,state.project.rig.image.width),clamp(((y-r.top)/k-v.offset[1])/v.scale,0,state.project.rig.image.height)];}
function renderOverlay(){if(!avatar)return;overlay.setAttribute('viewBox',`0 0 ${overlay.clientWidth} ${overlay.clientHeight}`);const drawing=state.drawing;overlay.classList.toggle('editing',state.tool==='contour'||!!drawing||!!state.pickMotionAnchor);const pts=drawing||getPoints();if(state.selected==='rig-strands'&&!drawing){overlay.innerHTML=state.project.rig.strands.map((strand,si)=>`<polyline points="${strand.nodes.map(screenPoint).map(p=>p.join(',')).join(' ')}" fill="none" stroke="#ffd28a" stroke-width="1.5"/>${strand.nodes.map((pt,ni)=>{const [x,y]=screenPoint(pt);return `<circle cx="${x}" cy="${y}" r="4" fill="#ffc278" stroke="#fff" data-strand="${si}" data-node="${ni}"/>`;}).join('')}`).join('');overlay.classList.add('editing');return;}if(!pts||state.tool==='grid'||state.mode!=='make'){overlay.innerHTML='';return;}const screen=pts.map(screenPoint);let extras='';const part=currentPart(),rig=state.project.rig;if(part.reg||part.appendage){const m=part.appendage||state.project.motions[part.id]||defaultMotion(part,rig),root=screenPoint(m.pivot),tip=screenPoint(m.tip);extras+=`<path d="M${root[0]},${root[1]}L${tip[0]},${tip[1]}" stroke="#ffce8b" stroke-width="2"/><circle cx="${root[0]}" cy="${root[1]}" r="6" fill="#ffbd73" stroke="white" data-motion-anchor="pivot"/><circle cx="${tip[0]}" cy="${tip[1]}" r="5" fill="#89c3ff" stroke="white" data-motion-anchor="tip"/>`;} if(part.id.startsWith('eye')){const index=part.id.includes('1')?1:0,roi=rig.eyes[index].roi.map(screenPoint);extras+=`<polygon points="${roi.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#ffc783" stroke-width="1" stroke-dasharray="3 3"/>`;if(state.tool==='contour')extras+=roi.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="3.5" data-point="${i}" data-roi="1" fill="#ffba71" stroke="#fff"/>`).join('');}if(part.id==='head'||part.id==='body'){const e=part.id==='head'?rig.head:rig.body.chest,center=screenPoint([e.cx,e.cy]),edge=screenPoint([e.cx+e.rx,e.cy+e.ry]);extras+=`<ellipse cx="${center[0]}" cy="${center[1]}" rx="${edge[0]-center[0]}" ry="${edge[1]-center[1]}" fill="none" stroke="#9bd5c0" stroke-width="1.3"/>`;}overlay.innerHTML=extras+`<${drawing?'polyline':'polygon'} points="${screen.map(p=>p.join(',')).join(' ')}" fill="${drawing?'none':'#83aaff0b'}" stroke="#9bc3ff" stroke-width="1.2" stroke-dasharray="${state.tool==='contour'?'':'4 4'}"/>${state.tool==='contour'||drawing?screen.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4.5" data-point="${i}" fill="#7aa9fb" stroke="#e9f3ff" stroke-width="1.4"/>`).join(''):''}`;}
function setTool(tool){if(tool==='grid'){guides.mode='animate';$('#reference-mode').value='animate';}if(state.mode!=='make')setMode('make');state.tool=tool;$$('[data-tool]').forEach(el=>el.classList.toggle('active',el.dataset.tool===tool));avatar?.setEditorMesh(tool==='grid');if(tool==='contour'){pause();guides.mode='original';$('#reference-mode').value='original';guides.on=true;$('#toggle-guides').classList.add('active');$('#canvas-hint').textContent='拖动控制点修正轮廓，然后更新分层与绑定';}else $('#canvas-hint').textContent='选择部件查看细节 · 导入配音让形象说话';renderOverlay();}
function setMode(mode){state.mode=mode;document.body.classList.toggle('mode-voice',mode==='voice');if(mode!=='make'){guides.mode='animate';$('#reference-mode').value='animate';}if(innerWidth<=700){document.body.classList.toggle('mobile-inspector',mode!=='make');document.body.classList.remove('mobile-layers');}$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));if(mode!=='live'){stopMic();stopCamera();}renderInspector();renderOverlay();}
function setBackground(v){stage.className='stage '+v;if(state.project)state.project.settings.background=v;}
async function saveProject(build=false){if(!state.project)return;build ||= state.needsBuild;const errors=MeshAvatar.validateRig(state.project.rig);if(errors.length)throw Error('参数无效，请修正后再保存：'+errors[0]);if(savePromise)return savePromise;const id=state.id,snapshot=copy(state.project);$('#save-state').textContent=build?'正在更新分层…':'正在保存…';if(build)setBusy(true,'正在切分像素图层与生成绑定…');
 savePromise=(async()=>{await api(`/api/projects/${id}/${build?'build':'save'}`,{rig:snapshot.rig,name:snapshot.name,settings:snapshot.settings,regions:snapshot.regions,keyframes:snapshot.keyframes,layerVisibility:snapshot.layerVisibility,motions:snapshot.motions});state.dirty=false;if(build){state.needsBuild=false;state.project=await api('/api/projects/'+id);await reloadAvatar();renderLayers();renderInspector();}await listProjects();toast(build?'分层与绑定已更新':'工程已保存到本机');})().catch(showError).finally(()=>{savePromise=null;setBusy(false);updateSave();});return savePromise;}
function pause(){state.playing=false;voice.pause();updatePlayButton();}
async function play(){if(!avatar||state.audioLoading)return;if(state.mode!=='make'||state.recording){guides.mode='animate';$('#reference-mode').value='animate';}state.mouth=null;if(state.time>=state.duration-.03)seek(0);state.playing=true;await audioCtx?.resume();if(voice.hasAttribute('src')){voice.currentTime=state.time;await voice.play().catch(e=>{state.playing=false;showError(Error('音频播放失败，请重新导入配音'));});}updatePlayButton();}
function updatePlayButton(){$('#play').innerHTML=icon(state.playing?'pause':'play',21);}
function seek(t){state.time=clamp(t,0,state.duration);if(voice.hasAttribute('src')&&Number.isFinite(voice.duration))voice.currentTime=clamp(t,0,voice.duration);drawTimeline();}
function timeLabel(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}.${String(Math.floor(t%1*100)).padStart(2,'0')}`;}
async function getAudioContext(){audioCtx ||= new AudioContext();await audioCtx.resume();return audioCtx;}
async function loadAudio(url,label='本地配音'){
 state.audioLoading=true;$('#play').disabled=true;
 try{
  const ctx=await getAudioContext(),r=await fetch(url);if(!r.ok)throw Error('无法读取配音文件');const buffer=await ctx.decodeAudioData(await r.arrayBuffer());audioBuffer=buffer;state.duration=buffer.duration;envelope=[];
  const data=buffer.getChannelData(0),rate=buffer.sampleRate;
  for(let t=0;t<buffer.duration;t+=1/60){const start=Math.floor(t*rate),end=Math.min(data.length,start+Math.floor(rate/60));let n=0;for(let i=start;i<end;i++)n+=data[i]*data[i];envelope.push(Math.sqrt(n/Math.max(1,end-start)));}
  if(!audioSource){audioSource=ctx.createMediaElementSource(voice);audioSource.connect(ctx.destination);}
  voice.src=url;await new Promise((resolve,reject)=>{voice.onloadedmetadata=resolve;voice.onerror=()=>reject(Error('浏览器无法播放此配音，请使用 WAV 或 MP3'));voice.load();});seek(0);pause();renderInspector();$('#audio-name')&&($('#audio-name').textContent=label);toast('配音已分析，点击播放预览口型');
 }finally{state.audioLoading=false;$('#play').disabled=false;}
}

async function loadDemoAudio(){state.audioLoading=true;$('#play').disabled=true;try{const file=await(await fetch('/demo-voice.wav')).blob();const r=await api('/api/projects/'+state.id+'/audio',file,true);await loadAudio(r.url+'?v='+Date.now(),'大肥鱼1号真实口播');}finally{state.audioLoading=false;$('#play').disabled=false;}}
function keyValue(channel,t,fallback){const keys=(state.project?.keyframes||[]).filter(k=>k.channel===channel).sort((a,b)=>a.time-b.time);if(!keys.length)return fallback;if(t<=keys[0].time)return keys[0].value;if(t>=keys.at(-1).time)return keys.at(-1).value;for(let i=1;i<keys.length;i++)if(t<=keys[i].time){const a=keys[i-1],b=keys[i],u=(t-a.time)/(b.time-a.time);return a.value+(b.value-a.value)*u;}return fallback;}
