 for(let i=0;i<=10;i++){const x=i/10*w;c.strokeStyle='#35415a';c.lineWidth=.6;c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();c.fillStyle='#a9bcd9';c.font='9px Harmony, sans-serif';c.fillText((state.duration*i/10).toFixed(state.duration<12?1:0)+'s',x+4,14);}
 for(let r=0;r<4;r++){c.fillStyle=r%2?'#22304755':'#2d3f5b33';c.fillRect(0,ruler+r*row,w,row);c.strokeStyle='#36435a';c.beginPath();c.moveTo(0,ruler+(r+1)*row);c.lineTo(w,ruler+(r+1)*row);c.stroke();}
 c.fillStyle='#8ca9ef';if(envelope){const max=Math.max(.04,...envelope),cy=ruler+row/2;for(let x=0;x<w;x+=2){const from=Math.floor(x/w*envelope.length),to=Math.max(from+1,Math.floor((x+2)/w*envelope.length));let v=0;for(let j=from;j<to;j++)v=Math.max(v,envelope[j]||0);const amp=Math.max(.7,v/max*(row/2-4));c.fillRect(x,cy-amp,1.3,amp*2);}}else{c.fillStyle='#9db2d3';c.font='10px Harmony,sans-serif';c.fillText('导入配音，自动生成口型驱动',16,ruler+row/2+3);}
