  if(state.expression==='closed'){params.eyeLOpen=0;params.eyeROpen=0;}if(state.expression==='halfLidded'){params.eyeLOpen=.45;params.eyeROpen=.45;}if(state.expression==='wink')params.eyeLOpen=0;if(state.expression==='smile')params.eyeSmile=.8;if(state.expression==='surprise'){params.eyeLOpen=1.15;params.eyeROpen=1.15;params.mouthOpen=Math.max(.4,params.mouthOpen);}
