  if(camStream&&camWorker&&!camBusy&&now-lastCam>70){const video=$('#camera-video');if(video.readyState>=2){camBusy=true;lastCam=now;createImageBitmap(video).then(bitmap=>{if(camWorker)camWorker.postMessage({type:'frame',frame:bitmap,timestamp:now},[bitmap]);else bitmap.close();}).catch(()=>camBusy=false);}}
