 const type=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));if(!type)throw Error('当前浏览器无法录制 WebM，请改用 Chrome 或 Edge');
