 const recorder=new MediaRecorder(stream,{mimeType:type,videoBitsPerSecond:7000000}),chunks=[];state.recorder=recorder;state.recording=true;const oldLoop=settings().loop;settings().loop=false;seek(0);let captureRaf;
 function capture(schedule=true){if(!state.recording)return;ctx.clearRect(0,0,1080,1080);if(settings().background!=='checker'){ctx.fillStyle={white:'#f1f2f5',green:'#00b140',dark:'#151b27'}[settings().background]||'#151b27';ctx.fillRect(0,0,1080,1080);}const a=$('#avatar'),scale=Math.min(1080/a.width,1080/a.height);ctx.drawImage(a,(1080-a.width*scale)/2,(1080-a.height*scale)/2,a.width*scale,a.height*scale);if(schedule)captureRaf=requestAnimationFrame(capture);}
