function download(url,name){const a=document.createElement('a');a.href=url;if(name)a.download=name;a.click();}
async function exportProject(){if(state.needsBuild){await saveProject(true);if(state.needsBuild)return;}else if(state.dirty)await saveProject();if(state.dirty)return;$('#export-dialog').showModal();$('#export-content').innerHTML=`<p class="note">${esc(state.project.name)} · 选择用途导出</p><button class="export-option" id="download-package">${icon('layers')}<div><b>可编辑角色包 .yxavatar</b><small>包含原图、精细分层、绑定、动作与独立播放器</small></div><span class="pill">继续制作</span></button><button class="export-option" id="download-compatible">${icon('link')}<div><b>兼容 Mesh Avatar .mavatar</b><small>精细图层合并回底图，供其他 Mesh Avatar 播放器使用</small></div></button><button class="export-option" id="download-png">${icon('image')}<div><b>透明 PNG 快照</b><small>保存当前表情与姿态</small></div></button><button class="export-option" id="export-record">${icon('record')}<div><b>WebM 动画 + 配音</b><small>1080 × 1080 / 30fps · 播放结束后自动完成</small></div></button><button class="export-option" id="import-package-export">${icon('folder')}<div><b>导入已有角色包</b><small>打开 .yxavatar / .mavatar 继续使用</small></div></button><p class="note" id="export-status" style="margin-top:16px">导出文件保存到本机，不会发布到网络。</p>`;}

let pendingImage=null,pendingAnchors=[],detectWorker=null;
async function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}
async function imageElement(url){const img=new Image();img.src=url;await img.decode();return img;}
async function selectImage(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请使用 PNG、JPG 或 WebP 图片');if(file.size>32*1024*1024)throw Error('请使用小于 32 MB 的图片');$('#import-dialog').showModal();$('#import-content').innerHTML='<div class="import-status"><span class="spinner" style="display:inline-block;vertical-align:middle;margin-right:12px"></span>读取图片并加载本地识别模型…</div>';pendingAnchors=[];
 const data=await fileData(file),img=await imageElement(data);if(img.naturalWidth>4096||img.naturalHeight>4096)throw Error('图片边长请控制在 4096 像素以内');
 const c=document.createElement('canvas');const scale=Math.min(1,2048/Math.max(img.naturalWidth,img.naturalHeight));c.width=Math.round(img.naturalWidth*scale);c.height=Math.round(img.naturalHeight*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);pendingImage={image:c.toDataURL('image/png'),name:file.name.replace(/\.[^.]+$/,'').slice(0,60),width:c.width,height:c.height,removeBackground:$('#remove-background').checked};
 const sourceBytes=await(await fetch('/projects/da-fei-yu-1/source.png')).arrayBuffer();const digest=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].join(',');if(await digest(await file.arrayBuffer())===await digest(sourceBytes)){pendingImage.image=data;pendingImage.name='大肥鱼1号副本';await generateImage(pendingImage);return;}
 try{detectWorker?.terminate();detectWorker=new Worker('/detect-worker.js');const result=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('面部识别超时')),35000);detectWorker.onmessage=({data})=>{clearTimeout(timer);data.error?reject(Error(data.error)):resolve(data);};detectWorker.onerror=e=>{clearTimeout(timer);reject(Error('本地模型无法加载'));};createImageBitmap(c).then(image=>detectWorker.postMessage({image},[image]));});detectWorker.terminate();detectWorker=null;
  if(result?.mask){const maskCanvas=document.createElement('canvas');maskCanvas.width=result.mask.width;maskCanvas.height=result.mask.height;const maskContext=maskCanvas.getContext('2d'),pixels=maskContext.createImageData(maskCanvas.width,maskCanvas.height);for(let i=0;i<result.mask.data.length;i++){pixels.data[i*4]=pixels.data[i*4+1]=pixels.data[i*4+2]=result.mask.data[i];pixels.data[i*4+3]=255;}maskContext.putImageData(pixels,0,0);pendingImage.categoryMask=maskCanvas.toDataURL('image/png');}
  const landmarks=result?.landmarks;
  if(landmarks){const pt=i=>[landmarks[i].x*c.width,landmarks[i].y*c.height];const eye0=[33,246,161,160,159,158,157,173,133,155,154,153,145,144,163,7].map(pt),eye1=[362,398,384,385,386,387,388,466,263,249,390,373,374,380,381,382].map(pt);const center=points=>[points.reduce((a,p)=>a+p[0],0)/points.length,points.reduce((a,p)=>a+p[1],0)/points.length];pendingImage.anchors=[center(eye0),center(eye1),center([pt(13),pt(14),pt(61),pt(291)])];pendingImage.eyeContours=[eye0,eye1];await generateImage(pendingImage);return;}
 }catch(e){console.warn(e.message);detectWorker?.terminate();detectWorker=null;}
 showCalibration();}
function showCalibration(){const p=pendingImage;$('#import-content').innerHTML=`<div class="field"><label for="new-name">形象名称</label><input id="new-name" value="${esc(p.name)}" maxlength="60" style="width:70%"></div><p class="note">这张图片没有识别到清晰面部。依次点击<strong>画面左眼、画面右眼、嘴巴中心</strong>，其余步骤自动完成。</p><div class="import-preview"><img id="calibration-image" src="${p.image}" alt="待制作的形象"><svg id="calibration-overlay" aria-label="依次定位双眼与嘴巴"></svg></div><p class="import-status" id="anchor-status">第 1 步：点击画面左眼中心</p><div class="import-actions"><button id="reset-anchors" class="secondary">重新定位</button><button id="generate-manual" class="primary" disabled>${icon('spark')}制作可动形象</button></div>`;$('#calibration-overlay').addEventListener('pointerdown',e=>{if(pendingAnchors.length>=3)return;const img=$('#calibration-image'),rect=img.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)return;pendingAnchors.push([(e.clientX-rect.left)/rect.width*p.width,(e.clientY-rect.top)/rect.height*p.height]);renderCalibration();});}
function renderCalibration(){const svg=$('#calibration-overlay'),img=$('#calibration-image'),r=img.getBoundingClientRect(),s=svg.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${s.width} ${s.height}`);svg.innerHTML=pendingAnchors.map(([x,y],i)=>{x=r.left-s.left+x/pendingImage.width*r.width;y=r.top-s.top+y/pendingImage.height*r.height;return `<circle cx="${x}" cy="${y}" r="6" stroke="#fff" fill="#5d93f3" stroke-width="2"/><text x="${x+10}" y="${y-10}" fill="#fff" font-size="14">${i+1}</text>`;}).join('');$('#anchor-status').textContent=['第 1 步：点击画面左眼中心','第 2 步：点击画面右眼中心','第 3 步：点击嘴巴中心','定位完成，点击制作'][pendingAnchors.length];$('#generate-manual').disabled=pendingAnchors.length!==3;}
async function generateImage(input){$('#import-content').innerHTML=`<p class="note">${esc(input.name)} · 正在从图片制作</p><div class="progress-steps">${['读取图片与面部定位','去背景与五官精细分层','生成头部、身体与嘴型绑定','载入可动形象预览'].map((t,i)=>`<div class="progress-step ${i===0?'done':i===1?'active':''}"><span class="progress-icon">${i===0?icon('check',15):i+1}</span><span>${t}</span></div>`).join('')}</div><p class="note">通常需要几秒到半分钟。复杂遮挡处可以在生成后继续修正。</p>`;
 try{const result=await api('/api/create',input);$$('.progress-step').forEach(x=>x.className='progress-step done');await listProjects();await openProject(result.id);$('#import-dialog').close();toast('形象已生成：现在可以播放、导入配音，或继续调整部件');}catch(e){$('#import-content').innerHTML=`<p class="note">制作没有完成：${esc(e.message)}</p><div class="import-actions"><button id="retry-image" class="primary">调整定位后重试</button></div>`;throw e;}}

