async function finishPart(){if(!state.drawing||state.drawing.length<3)return toast('请至少点击三个轮廓点');checkpoint();const id='part-'+Date.now().toString(36);state.project.regions.push({id,name:$('#part-name').value||'新部件',parent:'head',points:state.drawing,visible:true,sway:.8});state.selected=id;state.tab='motion';state.drawing=null;$('#draw-actions').hidden=true;changed(true);await saveProject(true);renderLayers();renderInspector();}
let parameterTimer,previewing=false;
function scheduleParameterPreview(){clearTimeout(parameterTimer);parameterTimer=setTimeout(()=>previewParameters().catch(showError),350);}
async function previewParameters(){if(previewing){scheduleParameterPreview();return;}const errors=MeshAvatar.validateRig(state.project.rig);const el=$('#parameter-status');if(errors.length){if(el)el.textContent='参数需要修正：'+errors[0];return;}previewing=true;try{await reloadAvatar();if(el)el.textContent='预览已更新；保存后保留这些参数。';}finally{previewing=false;}}
function stopPart(){state.sweep=null;state.partPreview=null;state.partValue={};state.pose={};state.expression='neutral';state.mouth=null;avatar?.setIsolatedPart(null);miniAvatar?.setIsolatedPart(null);renderInspector();}
function tryPart(type){pause();state.pose={};state.expression='neutral';state.partValue={};const part=currentPart();let selectedType=type|| (part.id==='head'?'head':part.id==='body'?'body':part.id.startsWith('eye')?'eyes':part.id==='mouth'?'mouth':part.appendage?'tail':part.reg?'part':'head');if(type==='tail'){const tail=partList().find(x=>x.appendage?.kind==='tail');if(tail){state.selected=tail.id;renderLayers();renderInspector();}}
 const current=currentPart();if(selectedType==='part'){state.partPreview={id:current.id};avatar?.setIsolatedPart(current.asset);miniAvatar?.setIsolatedPart(current.asset);}else if(selectedType==='tail'){state.partPreview={id:current.id};avatar?.setIsolatedPart(current.asset||null);miniAvatar?.setIsolatedPart(current.asset||null);}else{state.partPreview=null;state.sweep={type:selectedType,start:performance.now()};avatar?.setIsolatedPart('__pose__');miniAvatar?.setIsolatedPart('__pose__');}renderOverlay();}
