bind('#focus-part',()=>{if(!avatar)return;const pts=getPoints();if(!pts)return toast('请选择有轮廓的部件');const xs=pts.map(x=>x[0]),ys=pts.map(x=>x[1]),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2;state.editorView={zoom:1,panX:0,panY:0};avatar.setEditorView(state.editorView);let v=avatar.getViewport(),k=stage.clientWidth/v.width;const scale=Math.min(stage.clientWidth/(Math.max(...xs)-Math.min(...xs)+80),stage.clientHeight/(Math.max(...ys)-Math.min(...ys)+80));state.editorView.zoom=clamp(scale/(v.scale*k),.2,16);avatar.setEditorView(state.editorView);v=avatar.getViewport();state.editorView.panX=stage.clientWidth/2-(cx*v.scale+v.offset[0])*k;state.editorView.panY=stage.clientHeight/2-(cy*v.scale+v.offset[1])*k;guides.on=true;guides.mode='original';$('#reference-mode').value='original';updateView();});
