stage.addEventListener('wheel',e=>{if(e.target.closest('button,select'))return;e.preventDefault();const r=stage.getBoundingClientRect();zoomAt(Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top);},{passive:false});
stage.addEventListener('pointerdown',e=>{if(e.button===1||e.altKey){e.preventDefault();panDrag={x:e.clientX,y:e.clientY,px:state.editorView.panX,py:state.editorView.panY};stage.setPointerCapture(e.pointerId);}});
