stage.addEventListener('pointerup',()=>panDrag=null);
let drag=null;
overlay.addEventListener('pointerdown',e=>{if(e.altKey||e.button===1)return;if(state.pickMotionAnchor){const p=currentPart();state.project.motions[p.id]||=defaultMotion(p,state.project.rig);state.project.motions[p.id][state.pickMotionAnchor]=imagePoint(e.clientX,e.clientY);state.pickMotionAnchor=null;changed();renderOverlay();return;}if(e.target.dataset.strand!==undefined){checkpoint();drag={strand:Number(e.target.dataset.strand),node:Number(e.target.dataset.node)};overlay.setPointerCapture(e.pointerId);return;}if(state.drawing){state.drawing.push(imagePoint(e.clientX,e.clientY));renderOverlay();return;}if(e.target.dataset.motionAnchor){checkpoint();drag={motionAnchor:e.target.dataset.motionAnchor};overlay.setPointerCapture(e.pointerId);return;}const point=e.target.closest('[data-point]');if(!point||state.tool!=='contour')return;checkpoint();drag={roi:!!point.dataset.roi,index:Number(point.dataset.point),points:copy(getPoints()),start:imagePoint(e.clientX,e.clientY)};overlay.setPointerCapture(e.pointerId);});
overlay.addEventListener('pointermove',e=>{if(!drag)return;const pt=imagePoint(e.clientX,e.clientY);if(drag.motionAnchor){const part=currentPart();if(part.appendage){part.appendage[drag.motionAnchor]=pt;}else{state.project.motions[part.id]||=defaultMotion(part,state.project.rig);state.project.motions[part.id][drag.motionAnchor]=pt;}changed();renderOverlay();return;}if(drag.strand!==undefined){state.project.rig.strands[drag.strand].nodes[drag.node]=pt;changed(true);renderOverlay();return;}const part=currentPart(),r=state.project.rig,index=drag.index;
 if(part.reg)part.reg.points[index]=pt;
 else if(part.id.startsWith('eye')){const i=part.id.includes('1')?1:0;if(drag.roi){r.eyes[i].roi[index]=pt;changed(true);renderOverlay();return;}r.eyes[i].opening[index]=pt;const opening=r.eyes[i].opening,cx=opening.reduce((s,p)=>s+p[0],0)/opening.length,cy=opening.reduce((s,p)=>s+p[1],0)/opening.length;r.eyes[i].roi=opening.map(([x,y])=>[cx+(x-cx)*1.55,cy+(y-cy)*1.65]);}
 else if(part.appendage)part.appendage.outline[index]=pt;
 else{const e=part.id==='head'?r.head:part.id==='body'?r.body.chest:r.mouth.area,opposite=drag.points[(index+2)%4];e.cx=(pt[0]+opposite[0])/2;e.cy=(pt[1]+opposite[1])/2;e.rx=Math.max(5,Math.abs(pt[0]-opposite[0])/2);e.ry=Math.max(5,Math.abs(pt[1]-opposite[1])/2);if(part.id==='mouth'){r.mouth.cx=e.cx;r.mouth.cy=e.cy;r.mouth.halfLen=e.rx*.7;}}
 changed(true);renderOverlay();});
overlay.addEventListener('pointerup',()=>drag=null);overlay.addEventListener('pointercancel',()=>drag=null);
timeline.addEventListener('click',e=>{const r=timeline.getBoundingClientRect();seek((e.clientX-r.left)/r.width*state.duration);});
timeline.addEventListener('dblclick',e=>{const r=timeline.getBoundingClientRect(),row=Math.floor((e.clientY-r.top-22)/((r.height-22)/4));if(row<1)return;checkpoint();const ch=['','eyeLOpen','bodyAngleZ','tail'][row],t=clamp((e.clientX-r.left)/r.width)*state.duration,span=ch==='eyeLOpen'?.12:.35,base=ch==='eyeLOpen'?1:ch==='tail'?1:0,peak=ch==='eyeLOpen'?0:ch==='tail'?1.6:6;state.project.keyframes=state.project.keyframes.filter(k=>k.channel!==ch||Math.abs(k.time-t)>span);state.project.keyframes.push({channel:ch,time:Math.max(0,t-span),value:base},{channel:ch,time:t,value:peak},{channel:ch,time:Math.min(state.duration,t+span),value:base});changed();drawTimeline();toast('已添加一次'+(ch==='eyeLOpen'?'眨眼':ch==='tail'?'摆尾':'身体倾斜')+'，前后会回到自然状态');});
$('#image-input').addEventListener('change',e=>{selectImage(e.target.files[0]).catch(showError);e.target.value='';});
$('#audio-input').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;state.audioLoading=true;$('#play').disabled=true;try{toast('正在读取配音…');const v=await api('/api/projects/'+state.id+'/audio',f,true);await loadAudio(v.url,f.name);setMode('voice');}catch(e){showError(e);}finally{state.audioLoading=false;$('#play').disabled=false;}e.target.value='';});
$('#package-input').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{toast('正在导入角色包…');const p=await api('/api/import',f,true);await listProjects();await openProject(p.id);$('#export-dialog').close();toast('角色包已导入');}catch(e){showError(e);}e.target.value='';});
const drop=$('#drop-zone');['dragenter','dragover'].forEach(k=>drop.addEventListener(k,e=>{e.preventDefault();drop.classList.add('dragging');}));['dragleave','drop'].forEach(k=>drop.addEventListener(k,e=>{e.preventDefault();drop.classList.remove('dragging');if(k==='drop')selectImage(e.dataTransfer.files[0]).catch(showError);}));
$('#import-content').addEventListener('click',e=>{const id=e.target.closest('button')?.id;if(id==='reset-anchors'){pendingAnchors=[];renderCalibration();}if(id==='retry-image'){pendingAnchors=[];showCalibration();}if(id==='generate-manual'){pendingImage.name=$('#new-name').value;generateImage({...pendingImage,anchors:pendingAnchors}).catch(showError);}});
$('#export-content').addEventListener('click',e=>{const id=e.target.closest('button')?.id;Promise.resolve((async()=>{if(id==='download-package'||id==='download-compatible'){$('#export-status').textContent='正在打包角色资产…';const r=await api('/api/projects/'+state.id+'/export',{});download(id==='download-package'?r.url:r.compatibleUrl,state.project.name+(id==='download-package'?'.yxavatar':'.mavatar'));$('#export-status').textContent='角色包已导出。包含本地原图及已保存的分层数据。';}if(id==='download-png'){avatar.advance(0);download($('#avatar').toDataURL('image/png'),state.project.name+'-透明.png');}if(id==='export-record'){$('#export-dialog').close();await recordAnimation();}if(id==='import-package-export')$('#package-input').click();})()).catch(showError);});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||$('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();state.playing?pause():play().catch(showError);}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$('#undo').click();}if(e.key==='Escape'&&state.drawing)$('#cancel-part').click();});
window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue='';}});
new ResizeObserver(()=>{renderOverlay();drawTimeline();if(avatar)guides.draw(avatar.getViewport(),state.project.rig);}).observe(stage);
setupArt({api,state,save:saveProject,openProject,toast,error:showError});
window.__studio={state,guides,updateView,getTrackingStatus(){return {stream:!!camStream,ready:$('#camera-video').readyState,busy:camBusy,lastSend:performance.now()-lastCam,lastFace:performance.now()-faceLastSeen,stage:state.cameraStage};},tryPart,stopPart,get miniAvatar(){return miniAvatar;},startMic,stopMic,startCamera,stopCamera,get avatar(){return avatar;},openProject,saveProject,loadAudio,selectImage,generateImage,renderLayers,partList,play,pause,seek,recordAnimation,stopRecording};
const backgroundClock=new Worker('/clock-worker.js');backgroundClock.onmessage=()=>{if(document.hidden)frame(performance.now(),false);};
const initialQuery=new URLSearchParams(location.search);await listProjects();await openProject(initialQuery.get('project')||'da-fei-yu-1',{home:!initialQuery.has('editor')});requestAnimationFrame(frame);
